const qa=[
{keys:["knowledge graph","what is a kg","define kg"],title:"What is a knowledge graph?",body:"A knowledge graph is a structured representation of information in which entities are represented as nodes and relationships are represented as edges. Relationships have meaning, so systems can traverse the graph and infer connections instead of relying only on isolated stored facts.",points:["Nodes represent entities or concepts.","Edges represent typed relationships such as is-a, part-of, authored-by, or located-in.","Properties describe characteristics of nodes or relationships.","Inference rules can derive additional facts from graph structure."],trace:"Identify entities → connect them with typed predicates → apply graph traversal and inference."},
{keys:["semantic network","semantic net"],title:"What is a semantic network?",body:"A semantic network is a graph-based knowledge representation in which concepts are nodes and semantic relations are links. It is a foundational idea behind many knowledge representation and knowledge graph systems.",points:["Represents concepts and their relations visually.","Can express classification, part-whole, and association links.","Supports associative retrieval and inheritance when rules are defined."],trace:"Concept nodes + meaningful links form a semantic network."},
{keys:["ontology","what is an ontology"],title:"What is an ontology?",body:"An ontology is a formal, explicit specification of the concepts in a domain and the relationships, properties, constraints, and axioms that apply to them. It defines the vocabulary and meaning used by a knowledge graph.",points:["Classes define categories, such as Student and Course.","Individuals are specific members of classes.","Properties describe attributes and relations.","Axioms define constraints and logical statements."],trace:"Define domain vocabulary → define classes and properties → add axioms and individuals."},
{keys:["taxonomy","ontology vs taxonomy","difference between ontology and taxonomy"],title:"Ontology vs taxonomy",body:"A taxonomy is primarily a classification hierarchy, often a tree of broader and narrower categories. An ontology is richer: it can include classes, individuals, attributes, many relation types, constraints, and logical axioms. A taxonomy can be one component of an ontology.",points:["Taxonomy: focuses on hierarchical categorisation.","Ontology: models richer semantics and constraints.","Example taxonomy: Animal → Mammal → Cat.","Example ontology: Cat is-a Mammal; Cat has-property numberOfLegs=4; Cat located-in Home."],trace:"Compare scope: classification hierarchy versus a richer formal domain model."},
{keys:["is-a","isa relation","is a relationship"],title:"What does is-a mean?",body:"The is-a relation represents class membership or subclassing. For example, CS Student is-a Student and Student is-a Person. In a class hierarchy, this allows transitive classification and property inheritance.",points:["It is taxonomic / hierarchical.","It supports inheritance of applicable parent properties.","If A is-a B and B is-a C, infer A is-a C when the relation is modelled transitively."],trace:"A → is-a → B → is-a → C; derive A → is-a → C."},
{keys:["part-of","part of relationship","meronym"],title:"What does part-of mean?",body:"Part-of is a meronymic relation: it connects a component to the larger whole that contains or includes it. For example, a course can be part of a curriculum. Do not confuse part-of with is-a: a course is not a type of curriculum; it is a component of one.",points:["is-a expresses category membership or subclassing.","part-of expresses component-to-whole structure.","Transitivity is a modelling choice and should be validated for the domain."],trace:"Course → part-of → Curriculum; Curriculum → part-of → Programme."},
{keys:["has-property","property relation"],title:"What is has-property?",body:"has-property associates an entity or class with an attribute or value. For example, Course has-property credits=4. In an implementation, attributes may be stored directly on nodes or represented as explicit edges, depending on the graph model.",points:["Properties describe entities or relations.","Values may be strings, numbers, dates, booleans, or other entities.","Inheritance rules determine whether a property is passed to subclasses."],trace:"Entity → has-property → attribute/value."},
{keys:["inheritance","property inheritance"],title:"How does inheritance work in a knowledge graph?",body:"Inheritance allows a specific class to receive applicable properties from a more general parent class. If CS Student is-a Student and Student is-a Person, then CS Student may inherit Student properties and Person properties. The system follows the is-a hierarchy and collects properties according to the configured rules.",points:["Direct properties belong to the entity itself.","Inherited properties originate from ancestors.","More specific values may override general defaults, depending on the rule system.","Inheritance should be limited to relations for which it makes semantic sense."],trace:"CS Student → Student → Person; collect properties at each ancestor."},
{keys:["property propagation","propagation"],title:"What is property propagation?",body:"Property propagation is the controlled transfer of properties through semantic relationships. In this project, properties propagate along is-a class hierarchies. It is not safe to propagate every property along every relation: the system needs explicit propagation rules.",points:["Identify allowed propagation relation types.","Traverse ancestor paths.","Collect inherited attributes.","Resolve conflicts or overrides when two ancestors define different values."],trace:"Find ancestors → read their properties → apply inheritance and conflict rules."},
{keys:["transitive","transitivity"],title:"What is transitive inference?",body:"A relation is transitive if A related to B and B related to C allows the conclusion A related to C. Subclass relations are commonly treated transitively. Part-of may or may not be transitive depending on the domain's semantics.",points:["Premise 1: A is-a B.","Premise 2: B is-a C.","Conclusion: A is-a C.","Always verify whether the relation is intended to be transitive."],trace:"Apply a transitivity rule to a two-edge path."},
{keys:["default reasoning","defeasible reasoning"],title:"What is default reasoning?",body:"Default reasoning draws a typical conclusion when there is no known contrary evidence. It is defeasible: the conclusion can be withdrawn when a more specific exception is discovered. Example: birds normally fly, but penguins are birds that normally do not fly.",points:["A default is a typical rule, not an absolute truth.","An exception provides more specific evidence.","The exception blocks or overrides the default conclusion.","The reasoner should record why a conclusion was accepted or rejected."],trace:"General default → check specific exceptions → accept or defeat conclusion."},
{keys:["exception","exception handling","default exception"],title:"How are exceptions handled?",body:"An exception is a more specific fact that defeats a general default. If the system assumes birds normally fly but knows that penguins are non-flying birds, it should not infer that a penguin flies. Specific knowledge takes precedence over a broad default.",points:["Store the general default rule.","Store the exception condition or explicit contrary fact.","Check for exceptions before accepting the default conclusion.","Explain which exception defeated the rule."],trace:"Bird normally flies; Penguin is a bird; Penguin is a non-flying exception; therefore do not infer Penguin flies."},
{keys:["non-monotonic","nonmonotonic"],title:"What is non-monotonic reasoning?",body:"Non-monotonic reasoning is reasoning in which adding new information can invalidate an earlier conclusion. Default reasoning is a common example: a bird may initially be assumed to fly, but learning that it is a penguin can retract that conclusion.",points:["Conclusions are defeasible.","New evidence may require retraction.","Useful for commonsense knowledge and exceptions.","Different from classical monotonic logic."],trace:"Initial facts → provisional default conclusion → new exception → retract conclusion."},
{keys:["monotonic reasoning","monotonic logic"],title:"Monotonic vs non-monotonic reasoning",body:"In monotonic logic, adding premises cannot invalidate a conclusion already entailed by the earlier premises. In non-monotonic logic, new information may defeat a provisional conclusion. Classical first-order logic is monotonic; default reasoning is typically non-monotonic.",points:["Monotonic: conclusions remain valid as premises grow.","Non-monotonic: conclusions can be withdrawn.","Use monotonic rules for strict logical entailment.","Use defeasible rules for typical assumptions with exceptions."],trace:"Compare whether adding facts can retract an existing conclusion."},
{keys:["open world","open-world"],title:"What is the Open World Assumption?",body:"Under the Open World Assumption (OWA), the absence of a fact does not mean the fact is false. It may simply be unknown or not yet recorded. This is common in semantic web and ontology settings.",points:["Not known does not mean false.","Useful when knowledge is incomplete or distributed.","A missing relationship should not automatically be interpreted as its negation."],trace:"Check whether a statement is entailed; if not, treat it as unknown rather than false."},
{keys:["closed world","closed-world"],title:"What is the Closed World Assumption?",body:"Under the Closed World Assumption (CWA), a system treats facts not present in a database as false within a defined scope. This is common in many traditional database applications, but it differs from the open-world approach used in many ontology systems.",points:["Not recorded is treated as false within the database scope.","Useful when the database is considered complete for a query.","Do not confuse missing data with a logical contradiction."],trace:"Check stored facts; absent facts are considered false only under the chosen closed-world policy."},
{keys:["rdf","resource description framework"],title:"What is RDF?",body:"RDF (Resource Description Framework) is a W3C standard data model for describing resources using subject-predicate-object triples. Each triple states that a subject has a relationship (predicate) to an object.",points:["Subject: the resource being described.","Predicate: the named property or relation.","Object: a resource or literal value.","RDF graphs are sets of triples and can be queried with SPARQL."],trace:"Example: (Alice, studies, ComputerScience)."},
{keys:["rdfs","rdf schema"],title:"What is RDFS?",body:"RDF Schema (RDFS) extends RDF with a basic vocabulary for describing classes and properties. It includes concepts such as rdfs:Class, rdfs:subClassOf, rdfs:domain, and rdfs:range, enabling basic schema-level inference.",points:["rdfs:subClassOf expresses class hierarchy.","rdfs:domain describes the subject class for a property.","rdfs:range describes the value class or datatype.","RDFS reasoning can infer types from schema statements."],trace:"RDF facts + RDFS schema vocabulary → schema-based entailments."},
{keys:["owl","web ontology language"],title:"What is OWL?",body:"OWL (Web Ontology Language) is a W3C family of ontology languages for expressing rich knowledge about classes, properties, individuals, and logical constraints. OWL supports more expressive modelling than basic RDF Schema and is grounded in description logic.",points:["Can define equivalent and disjoint classes.","Can express property characteristics and restrictions.","Supports formal ontology reasoning.","OWL profiles trade expressivity for computational efficiency."],trace:"Ontology axioms are processed by an OWL reasoner to derive logical entailments."},
{keys:["sparql"],title:"What is SPARQL?",body:"SPARQL is the standard query language for RDF data. It allows users to match graph patterns, retrieve bindings, and perform updates where supported. It is often compared to SQL, but it queries RDF graph patterns rather than relational tables.",points:["SELECT retrieves variable bindings.","ASK checks whether a pattern exists.","CONSTRUCT builds an RDF graph from matches.","Queries use triple patterns and optional graph patterns."],trace:"Write a graph pattern → match triples → return variable bindings or a constructed graph."},
{keys:["neo4j"],title:"What is Neo4j?",body:"Neo4j is a graph database using a property graph model. It stores nodes, relationships, labels, and key-value properties. Its declarative query language is Cypher, which uses a pattern-oriented syntax to traverse and update graphs.",points:["Nodes represent entities.","Relationships are directed and typed.","Properties can be stored on nodes and relationships.","Cypher is used to query and update the graph."],trace:"Model nodes and edges → persist in Neo4j → query patterns with Cypher."},
{keys:["cypher"],title:"What is Cypher?",body:"Cypher is a declarative graph query language associated with Neo4j. It describes graph patterns using node and relationship patterns, making connected data queries readable.",points:["MATCH finds graph patterns.","WHERE filters matches.","RETURN selects results.","CREATE and MERGE create graph structures."],trace:"Pattern matching over nodes and relationships."},
{keys:["property graph"],title:"What is a property graph?",body:"A property graph represents data using nodes and relationships. Nodes and relationships can have labels or types and key-value properties. This model is common in native graph databases such as Neo4j.",points:["Nodes represent entities.","Relationships connect nodes and have types.","Properties can exist on both nodes and relationships.","A property graph is not identical to an RDF graph."],trace:"Node + relationship + properties form a property graph."},
{keys:["triple store"],title:"What is an RDF triple store?",body:"An RDF triple store is a database designed to store and query RDF triples. It commonly supports SPARQL and may provide RDF or OWL entailment regimes.",points:["Stores subject-predicate-object statements.","Uses IRIs and literals to identify resources and values.","Often supports SPARQL queries.","Useful for linked data and semantic web applications."],trace:"Persist RDF graph triples → query with SPARQL."},
{keys:["bfs","breadth first"],title:"What is Breadth-First Search?",body:"Breadth-First Search (BFS) explores a graph level by level, visiting all immediate neighbours before moving to the next depth. It typically uses a queue and finds shortest paths in unweighted graphs.",points:["Uses a FIFO queue.","Marks visited nodes to avoid repeated processing.","Time complexity is O(V + E) with adjacency lists.","Useful for shortest unweighted paths and neighbourhood exploration."],trace:"Enqueue start → dequeue node → enqueue unvisited neighbours."},
{keys:["dfs","depth first"],title:"What is Depth-First Search?",body:"Depth-First Search (DFS) explores as far as possible along one branch before backtracking. It can be implemented with recursion or an explicit stack.",points:["Uses recursion or a stack.","Marks visited nodes to avoid cycles.","Time complexity is O(V + E) with adjacency lists.","Useful for reachability, connected components, and traversal."],trace:"Visit node → recursively explore unvisited neighbours → backtrack."},
{keys:["graph traversal","traverse graph"],title:"What is graph traversal?",body:"Graph traversal is the systematic process of visiting nodes or edges in a graph. Common approaches are BFS and DFS. In a knowledge graph, traversal can follow selected relation types to find relevant facts or reasoning paths.",points:["BFS explores by distance from the start node.","DFS explores a branch deeply before backtracking.","Visited sets prevent infinite loops in cyclic graphs.","Semantic traversal can restrict edges to is-a or part-of."],trace:"Choose start node and edge constraints → traverse reachable graph."},
{keys:["graph embedding","embeddings"],title:"What are graph embeddings?",body:"Graph embeddings map nodes, edges, or subgraphs into low-dimensional vector spaces. The vectors are designed to preserve useful graph structure or semantics and can support similarity, link prediction, and machine learning tasks.",points:["Represent graph entities as vectors.","Learn structural or semantic similarity.","Can support link prediction and recommendations.","Embeddings are learned representations, not explicit logical proofs."],trace:"Graph structure → embedding model → vector representation → downstream ML task."},
{keys:["knowledge graph completion","link prediction"],title:"What is knowledge graph completion?",body:"Knowledge graph completion aims to predict missing entities or relationships. It may use logical rules, graph embeddings, path patterns, or machine learning. Predictions should be distinguished from facts that are explicitly known or logically entailed.",points:["Detects likely missing links.","Can use embedding models or rule mining.","Useful for data enrichment and recommendation.","Predicted links need confidence and validation."],trace:"Known graph patterns → candidate relation scoring → validation."},
{keys:["entity resolution"],title:"What is entity resolution?",body:"Entity resolution identifies records that refer to the same real-world object, even when names or attributes differ. It helps avoid duplicate nodes and inconsistent graph structure.",points:["Compare names and identifiers.","Use contextual attributes and relationships.","Resolve duplicates or link aliases.","Track uncertainty and provenance for ambiguous matches."],trace:"Candidate records → similarity/context checks → match, merge, or review."},
{keys:["data integration"],title:"What is data integration in knowledge graphs?",body:"Data integration combines information from multiple sources into a coherent graph. It requires mapping source schemas to a common ontology, resolving entity identities, normalising values, and preserving provenance.",points:["Schema alignment maps fields to ontology concepts.","Entity resolution links duplicate identities.","Data transformation normalises values.","Provenance records where facts came from."],trace:"Sources → schema mapping → entity resolution → unified graph."},
{keys:["semantic search"],title:"What is semantic search?",body:"Semantic search retrieves information using meaning, context, and relationships rather than relying only on exact keyword overlap. A knowledge graph can enrich search by expanding queries through synonyms, types, and connected entities.",points:["Understands related concepts and context.","Can use ontology expansion and graph traversal.","May combine vector similarity with symbolic graph constraints.","Results should expose evidence and source provenance."],trace:"Interpret query → expand semantic context → retrieve connected facts."},
{keys:["rag","retrieval augmented"],title:"What is Retrieval-Augmented Generation (RAG)?",body:"RAG is a pattern in which a system retrieves relevant information from a knowledge source and supplies it to a language model as context before generating an answer. Graph-based RAG retrieves entities, relations, and connected subgraphs to ground responses.",points:["Retrieve relevant passages or graph neighbourhoods.","Augment the model prompt with evidence.","Generate an answer grounded in retrieved context.","Cite or expose sources to reduce unsupported claims."],trace:"Question → retrieve graph context → augment prompt → generate grounded response."},
{keys:["applications","use cases","application of knowledge graph"],title:"Applications of knowledge graphs",body:"Knowledge graphs are useful when data is connected and context matters. They are used in search, recommendations, fraud detection, healthcare terminology, product catalogues, digital libraries, enterprise data integration, and scientific discovery.",points:["Education: curriculum mapping and prerequisite discovery.","Healthcare: linking diseases, symptoms, drugs, and clinical concepts.","E-commerce: product attributes, compatibility, and recommendations.","History: people, places, events, and timelines.","Enterprise: customers, assets, services, and processes."],trace:"Choose a domain → define its entities and relations → model queries and reasoning needs."},
{keys:["advantages","benefits"],title:"Advantages of knowledge graphs",body:"Knowledge graphs make relationships explicit, integrate heterogeneous information, support semantic search, and enable explainable inference. They can be extended incrementally as new entities and relations are added.",points:["Flexible representation of connected data.","Explicit semantics and reusable domain vocabulary.","Supports inheritance and rule-based reasoning.","Can provide explainable paths for answers.","Useful for integrating data from multiple sources."],trace:"Structured entities + typed relationships + reasoning rules provide semantic context."},
{keys:["limitations","disadvantages","challenges"],title:"Limitations and challenges",body:"Knowledge graphs require careful ontology design, entity resolution, data quality management, and maintenance. Large-scale reasoning can be computationally expensive, and incomplete or inconsistent data can lead to weak conclusions.",points:["Ontology creation can be time-consuming.","Entity identity and duplicate resolution are difficult.","Rules may create unintended inferences if poorly designed.","Graph updates and provenance need governance.","No knowledge base can guarantee every possible answer."],trace:"Assess modelling quality, data completeness, reasoning complexity, and maintenance costs."},
{keys:["architecture","system architecture"],title:"Project system architecture",body:"The project can be organised into a user interface, query interpreter, knowledge graph store, inference engine, and answer explanation layer. The user asks a question; the interpreter identifies intent and entities; graph traversal and rules derive facts; the response includes an answer and trace.",points:["UI: graph explorer, builder, assistant, and dashboards.","Query interpreter: normalises and classifies questions.","Graph store: entities, relations, properties, and metadata.","Reasoner: transitivity, inheritance, defaults, and exceptions.","Explanation: answer, evidence, and derivation trace."],trace:"User query → intent parsing → graph lookup → inference → answer explanation."},
{keys:["project objective","objective of this project","aim of this project"],title:"Project objectives",body:"The main objective is to develop an interactive knowledge graph for a selected domain and implement semantic-network reasoning so that queries can be answered through graph-based inference rather than only by retrieving stored facts.",points:["Choose and model a domain.","Represent is-a, part-of, and other semantic relations.","Implement inheritance and property propagation.","Demonstrate default reasoning with exceptions.","Provide natural-language or structured query exploration."],trace:"Project description mapped to modelling, reasoning, and query deliverables."},
{keys:["viva","interview questions","oral exam"],title:"Viva preparation: key questions",body:"Important viva areas include graph structure, ontology versus taxonomy, is-a versus part-of, inheritance, property propagation, transitivity, default reasoning, exceptions, RDF triples, OWL, SPARQL, and the limitations of a rule-based assistant.",points:["Why use a knowledge graph instead of a relational table?","How is is-a different from part-of?","What is property propagation?","Why is default reasoning non-monotonic?","How does the query engine explain its answers?","What are the limitations and future enhancements?"],trace:"Prepare definitions → give examples → explain implementation → discuss limitations."},
{keys:["relational database","database vs graph"],title:"Knowledge graph vs relational database",body:"Relational databases organise data into tables with rows, columns, and keys. Knowledge graphs organise data as entities and relationships. Both can represent connected information, but graph models make relationships first-class and can make multi-hop traversal more natural.",points:["Relational model: tables, joins, keys, constraints.","Graph model: nodes, edges, labels, properties.","Relational databases are strong for structured transactional workloads.","Graph databases are useful for highly connected relationship queries.","The choice depends on data shape and workload."],trace:"Compare data model and query patterns rather than treating one as universally better."},
{keys:["why knowledge graph","why use knowledge graphs"],title:"Why use a knowledge graph?",body:"Use a knowledge graph when the relationships between things are as important as the things themselves. It supports connected exploration, semantic integration, multi-hop queries, and reasoning over class hierarchies and domain rules.",points:["Makes relationships explicit.","Connects information from different sources.","Supports semantic queries and inference.","Can explain conclusions through graph paths."],trace:"Identify relationship-heavy use case → model nodes and edges → query connected structure."},
{keys:["project limitation","does it answer every","all questions"],title:"Can this assistant answer absolutely every question?",body:"No finite offline knowledge pack can guarantee an answer to every possible question. This version covers a broad curated set of core knowledge graph and semantic reasoning topics, plus user-created graph data. It deliberately says when it cannot ground an answer. For broader open-ended coverage, connect a language model through a secure backend and retrieve graph evidence (graph-assisted RAG).",points:["This version: local curated Q&A and rule-based graph inference.","Unknown questions: explicit not-found response rather than invented facts.","Future: backend LLM API + graph retrieval + source citations.","Keep the graph as the trusted domain source."],trace:"Coverage is bounded by the local knowledge pack and implemented query patterns."}
];
const quiz=[
["Which component represents an entity in a graph? ",["Edge","Node","Predicate","Query"],1,"A node (vertex) represents an entity. An edge represents the relationship between nodes."],
["What does is-a usually represent?",["Part-whole composition","Taxonomic classification","A timestamp","A database join"],1,"is-a represents class membership or subclassing and can support inheritance."],
["Which relation means component-to-whole?",["is-a","has-property","part-of","related-to"],2,"part-of links a component to the larger whole that contains it."],
["What is an RDF statement made of?",["Node, edge, label","Subject, predicate, object","Table, row, key","Class, method, object"],1,"RDF represents information as subject-predicate-object triples."],
["What happens in non-monotonic reasoning?",["Conclusions can be retracted","Facts cannot be added","All relations are symmetric","Queries are impossible"],0,"New information can defeat a previous default conclusion in non-monotonic reasoning."],
["What does SPARQL query?",["RDF graphs","CSS styles","Image files","Operating systems"],0,"SPARQL is the standard query language for RDF data."],
["What is property propagation?",["Deleting attributes","Passing applicable properties through semantic paths","Compressing graph images","Sorting nodes alphabetically"],1,"Property propagation transfers properties along defined relations such as is-a inheritance."],
["Which algorithm uses a queue?",["DFS","BFS","Binary search","Quick sort"],1,"Breadth-First Search commonly uses a FIFO queue."],
["What does the Open World Assumption mean?",["Missing facts are false","Missing facts are unknown, not necessarily false","Every fact is true","The graph is public"],1,"Under OWA, absence of a fact does not imply its negation."],
["What is an ontology?",["A formal specification of domain concepts and relations","A graph drawing library","A programming language","A type of CPU"],0,"An ontology defines concepts, properties, relations, constraints, and axioms for a domain."]
];
let db=loadDb(),zoom=1,selected=null,qi=0,score=0,answered=false;
function loadDb(){try{return JSON.parse(localStorage.getItem("gm-ultimate-db"))||{entities:structuredClone(entities),relations:structuredClone(relations)}}catch{return{entities:structuredClone(entities),relations:structuredClone(relations)}}}
function save(){localStorage.setItem("gm-ultimate-db",JSON.stringify(db));refresh();renderEntities();fillSelects();drawGraph();renderDerived();renderLibrary()}
function E(id){return db.entities.find(x=>x.id===id)}
function byName(name){return db.entities.find(x=>x.name.toLowerCase()===name.toLowerCase())}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(s){let d=document.createElement("div");d.className="toast";d.textContent=s;$("#toastHost").append(d);setTimeout(()=>d.remove(),2800)}
function nav(p){$$(".page").forEach(x=>x.classList.remove("active"));$("#page-"+p)?.classList.add("active");$$(".nav").forEach(x=>x.classList.toggle("active",x.dataset.page===p));$("#crumb").textContent=({dashboard:"Dashboard",assistant:"Domain AI assistant",graph:"Graph explorer",builder:"Knowledge builder",reasoner:"Inference engine",ontology:"Ontology studio",knowledge:"Knowledge library",quiz:"Learning & quiz",documentation:"Documentation"})[p];if(p==="graph")drawGraph();if(p==="builder"){renderEntities();fillSelects()}if(p==="reasoner")renderDerived();location.hash=p}
document.addEventListener("click",e=>{let a=e.target.closest("[data-page]");if(a){e.preventDefault();nav(a.dataset.page)}let g=e.target.closest("[data-go]");if(g)nav(g.dataset.go);let q=e.target.closest("[data-q]");if(q){nav("assistant");ask(q.dataset.q)}});
function ancestors(id,seen=new Set()){let a=[];db.relations.forEach(([s,r,t])=>{if(s===id&&r==="is-a"&&!seen.has(t)){seen.add(t);a.push(t,...ancestors(t,seen))}});return a}
function derive(){let f=[];db.entities.forEach(e=>{let aa=ancestors(e.id);aa.forEach(a=>f.push({text:`${e.name} is-a ${E(a)?.name}`,why:`Transitive is-a path: ${[e.name,...aa.map(x=>E(x)?.name)].join(" → ")}`,rule:"TRANSITIVITY"}));let ps=new Map();aa.forEach(a=>E(a)?.properties.forEach(p=>ps.set(p,E(a).name)));ps.forEach((from,p)=>f.push({text:`${e.name} inherits ${p}`,why:`Property propagated from ${from}.`,rule:"INHERITANCE"}))});db.relations.forEach(([s,r,t])=>{if(r==="part-of")db.relations.filter(x=>x[0]===t&&x[1]==="part-of").forEach(x=>f.push({text:`${E(s)?.name} is part of ${E(x[2])?.name}`,why:`Part-of chain: ${E(s)?.name} → ${E(t)?.name} → ${E(x[2])?.name}`,rule:"PART-OF"}))});return f}
function refresh(){$("#entityCount").textContent=db.entities.length;$("#edgeCount").textContent=db.relations.length;$("#factCount").textContent=derive().length;$("#qaCount").textContent=qa.length+"+"}
function renderEntities(filter=""){if(!$("#entityRows"))return;$("#entityRows").innerHTML=db.entities.filter(e=>e.name.toLowerCase().includes(filter.toLowerCase())).map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td>${e.properties.length}</td><td><button class="del" data-delete="${e.id}">×</button></td></tr>`).join("")||'<tr><td colspan="5">No matching entities.</td></tr>'}
function fillSelects(){["source","target"].forEach(id=>{let s=$("#"+id);if(!s)return;let old=s.value;s.innerHTML=db.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("");if(E(old))s.value=old});preview()}
function preview(){if($("#edgePreview"))$("#edgePreview").textContent=`${E($("#source").value)?.name||"Source"} → ${$("#predicate").value} → ${E($("#target").value)?.name||"Target"}`}
function renderLibrary(filter=""){if(!$("#libraryGrid"))return;$("#libraryGrid").innerHTML=db.entities.filter(e=>(e.name+" "+e.description+" "+e.category).toLowerCase().includes(filter.toLowerCase())).map(e=>`<article class="panel library-card" data-open="${e.id}"><span class="type">${esc(e.category.toUpperCase())}</span><h3>${esc(e.name)}</h3><p>${esc(e.description)}</p><small>${e.properties.length} PROPERTIES · ASK ABOUT THIS ↗</small></article>`).join("")}
function drawGraph(){
 const svg=$("#graphSvg");if(!svg)return;
 // A detailed teaching map arranged in four clearly separated stages.
 const nodes=[
  {id:"knowledge-graph",x:190,y:125,label:["KNOWLEDGE GRAPH","connected information"],kind:"class"},
  {id:"semantic-network",x:190,y:265,label:["SEMANTIC NETWORK","concepts + meaningful links"],kind:"class"},
  {id:"entity",x:75,y:430,label:["ENTITY","the thing / concept"],kind:"instance"},
  {id:"node",x:305,y:430,label:["NODE","entity shown in graph"],kind:"instance"},
  {id:"edge",x:305,y:590,label:["EDGE","connection between nodes"],kind:"instance"},
  {id:"triple",x:75,y:590,label:["RDF TRIPLE","subject · predicate · object"],kind:"instance"},
  {id:"ontology",x:690,y:125,label:["ONTOLOGY","formal domain blueprint"],kind:"class"},
  {id:"class",x:575,y:285,label:["CLASS","a category / type"],kind:"class"},
  {id:"instance",x:805,y:285,label:["INSTANCE","one specific member"],kind:"instance"},
  {id:"is-a",x:575,y:455,label:["IS-A","type / category relation"],kind:"class"},
  {id:"property",x:805,y:455,label:["PROPERTY","detail or attribute"],kind:"instance"},
  {id:"taxonomy",x:690,y:625,label:["TAXONOMY","category hierarchy"],kind:"class"},
  {id:"inference",x:1190,y:125,label:["INFERENCE","derive new facts"],kind:"class"},
  {id:"semantic-reasoning",x:1190,y:285,label:["SEMANTIC REASONING","use meaning + graph paths"],kind:"class"},
  {id:"inheritance",x:1075,y:455,label:["INHERITANCE","pass down properties"],kind:"instance"},
  {id:"transitivity",x:1305,y:455,label:["TRANSITIVITY","follow relation chains"],kind:"instance"},
  {id:"default-reasoning",x:1075,y:625,label:["DEFAULT REASONING","assume what is typical"],kind:"instance"},
  {id:"exception",x:1305,y:625,label:["EXCEPTION","overrides a default"],kind:"instance"},
  {id:"RDF",x:285,y:835,label:["RDF","store facts as triples"],kind:"class"},
  {id:"RDFS",x:575,y:835,label:["RDFS","basic class vocabulary"],kind:"class"},
  {id:"OWL",x:865,y:835,label:["OWL","richer ontology rules"],kind:"class"},
  {id:"SPARQL",x:1155,y:835,label:["SPARQL","query an RDF graph"],kind:"class"}
 ];
 const edges=[
  ["knowledge-graph","semantic-network","represented as"],
  ["knowledge-graph","entity","contains"],
  ["knowledge-graph","node","uses"],
  ["entity","node","represented by"],
  ["node","edge","connected through"],
  ["edge","triple","can be expressed as"],
  ["ontology","class","defines"],
  ["ontology","property","defines"],
  ["class","instance","has members"],
  ["class","is-a","connected by"],
  ["is-a","taxonomy","builds"],
  ["inference","semantic-reasoning","part of"],
  ["semantic-reasoning","inheritance","can use"],
  ["semantic-reasoning","transitivity","can use"],
  ["semantic-reasoning","default-reasoning","can use"],
  ["default-reasoning","exception","blocked by"],
  ["RDF","triple","uses"],
  ["RDFS","ontology","extends"],
  ["OWL","ontology","expresses rules for"],
  ["SPARQL","RDF","queries"]
 ];
 const byId=Object.fromEntries(nodes.map(n=>[n.id,n]));
 const W=1400,H=930,NW=190,NH=66;
 let out=`<defs><marker id="simpleArrow" markerWidth="9" markerHeight="9" refX="7" refY="4" orient="auto"><path d="M0,0 L0,8 L8,4 z" fill="#91a8c8"/></marker></defs>
 <g class="graph-groups">
 <rect x="25" y="35" width="360" height="650" rx="18"/><rect x="500" y="35" width="380" height="650" rx="18"/><rect x="975" y="35" width="400" height="650" rx="18"/><rect x="25" y="755" width="1350" height="135" rx="18"/>
 <text x="45" y="70">1 · GRAPH FOUNDATIONS</text><text x="520" y="70">2 · HOW KNOWLEDGE IS MODELLED</text><text x="995" y="70">3 · HOW THE SYSTEM REASONS</text><text x="45" y="790">4 · COMMON STANDARDS &amp; QUERY LANGUAGE</text>
 </g><g transform="scale(${zoom})">`;
 edges.forEach(([a,b,r])=>{let u=byId[a],v=byId[b];if(!u||!v)return;let dx=v.x-u.x,dy=v.y-u.y,len=Math.hypot(dx,dy)||1;let sx=u.x+dx/len*NW*.42,sy=u.y+dy/len*NH*.42,ex=v.x-dx/len*NW*.42,ey=v.y-dy/len*NH*.42;let mx=(sx+ex)/2,my=(sy+ey)/2;out+=`<path class="edge ${r.includes("is-a")?"edge-isa":""}" marker-end="url(#simpleArrow)" d="M${sx} ${sy} L${ex} ${ey}"/><text class="edge-label" x="${mx}" y="${my-7}" text-anchor="middle">${esc(r)}</text>`});
 nodes.forEach(n=>{let e=E(n.id);if(!e)return;out+=`<g class="graph-node ${n.kind==="class"?"class-node":""} ${selected===n.id?"selected":""}" data-node="${esc(n.id)}" transform="translate(${n.x} ${n.y})"><rect class="simple-node" x="-${NW/2}" y="-${NH/2}" width="${NW}" height="${NH}" rx="11"/><text class="simple-node-name" y="-5">${esc(n.label[0])}</text><text class="simple-node-sub" y="17">${esc(n.label[1])}</text></g>`});
 out+=`</g><text class="graph-hint" x="700" y="915" text-anchor="middle">Follow the numbered sections from left to right, then explore the standards below. Select any box for details.</text>`;
 svg.setAttribute("viewBox",`0 0 ${W} ${H}`);svg.innerHTML=out;
 $$(".graph-node",svg).forEach(n=>n.addEventListener("click",()=>inspect(n.dataset.node)));
}
function inspect(id){selected=id;drawGraph();let e=E(id),links=db.relations.filter(x=>x[0]===id||x[2]===id),props=[...e.properties];ancestors(id).forEach(a=>E(a)?.properties.forEach(p=>props.push(p)));$("#nodeInfo").className="node-info";$("#nodeInfo").innerHTML=`<span class="kind">${esc(e.category.toUpperCase())}</span><h2>${esc(e.name)}</h2><p>${esc(e.description)}</p><h4>PROPERTIES</h4><ul>${props.map(p=>`<li>${esc(p)}</li>`).join("")||"<li>None stored</li>"}</ul><h4>CONNECTED RELATIONSHIPS</h4><ul>${links.map(([s,r,t])=>`<li>${esc(E(s)?.name)} <b>${esc(r)}</b> ${esc(E(t)?.name)}</li>`).join("")||"<li>No explicit edges</li>"}</ul>`}
function renderDerived(){if(!$("#derivedRows"))return;let f=derive();$("#derivedCount").textContent=f.length+" DERIVED FACTS";$("#derivedRows").innerHTML=f.slice(0,50).map(x=>`<div class="fact-row"><i>✓</i><span><b>${esc(x.text)}</b><small>${esc(x.why)} · ${x.rule}</small></span></div>`).join("")||'<p class="muted">No inferred facts. Add semantic edges to enable reasoning.</p>'}
function scoreQa(q){let s=q.toLowerCase().replace(/[^a-z0-9\s-]/g," ").split(/\s+/).filter(w=>w.length>2);let best=null,bestScore=0;qa.forEach(item=>{let sc=0;item.keys.forEach(k=>{let kl=k.toLowerCase();if(q.toLowerCase().includes(kl))sc=Math.max(sc,kl.split(" ").length*3+kl.length/20)});item.title.toLowerCase().split(/\s+/).forEach(w=>{if(s.includes(w))sc+=1});if(sc>bestScore){bestScore=sc;best=item}});return bestScore>=2?best:null}
function answer(q){let l=q.toLowerCase(),best=scoreQa(q),exact=db.entities.find(e=>l.includes(e.name.toLowerCase())),title="",body="",points=[],trace="";
 if(/^(hi|hello|hey)\b/.test(l)){title="Hello!";body="I'm GraphMind. I can help with knowledge graphs, semantic networks, ontology design, inference, logic, RDF/OWL, SPARQL, graph databases, applications, and project viva preparation.";trace="Greeting recognised; no graph inference needed."}
 else if(/how many|count|number of/.test(l)&&/entity|entities|node|nodes|relation|edge/.test(l)){title="Current graph statistics";body=`Your editable graph currently contains ${db.entities.length} entities and ${db.relations.length} explicit relationships, with ${derive().length} derived conclusions.`;points=[`Entities: ${db.entities.length}`,`Relationships: ${db.relations.length}`,`Derived conclusions: ${derive().length}`];trace="Counted current local graph records."}
 else if(/list.*(entity|entities|concept|node)|show.*(entity|entities|concept|node)/.test(l)){title="Entities in the current graph";body="Here are the concepts currently loaded in the knowledge base.";points=db.entities.slice(0,80).map(e=>`${e.name} — ${e.category}`);trace="Enumerated the graph entity registry."}
 else if(exact&&(/inherit|propert|attribute/.test(l))){let aa=ancestors(exact.id),all=[...exact.properties];aa.forEach(a=>E(a)?.properties.forEach(p=>all.push(p)));title=`Properties of ${exact.name}`;body=`${exact.name} has ${exact.properties.length} direct properties and inherits ${all.length-exact.properties.length} properties through its is-a ancestors.`;points=[...exact.properties.map(x=>"Direct: "+x),...aa.flatMap(a=>E(a)?.properties.map(x=>`Inherited from ${E(a).name}: ${x}`)||[])];trace=[exact.name,...aa.map(a=>E(a)?.name)].join(" → ")+"; collect ancestor properties."}
 else if(exact&&(/what is|who is|define|describe|explain/.test(l))){title=`About ${exact.name}`;body=exact.description;points=[`Category: ${exact.category}`,...exact.properties];let aa=ancestors(exact.id);aa.forEach(a=>points.push("is-a "+E(a)?.name));trace=aa.length?[exact.name,...aa.map(a=>E(a)?.name)].join(" → "):"Retrieved the entity description and properties."}
 else if(/which.*(part|course)|part of|part-of/.test(l)){title="Part-of relationships";body="These are the component-to-whole relations currently represented in the graph.";points=db.relations.filter(x=>x[1]==="part-of").map(([s,r,t])=>`${E(s)?.name} part-of ${E(t)?.name}`);trace="Traversed explicit part-of edges."}
 else if(/default|exception|visiting professor|penguin|bird/.test(l)&&(/reason|fly|teach|exception|default|professor/.test(l))){title="Default reasoning with exceptions";body="A general default is a defeasible assumption, not an absolute fact. For the classic example, birds normally fly; penguins are birds but are a known exception, so the default conclusion is blocked. In the university example, professors typically teach, but a visiting professor may be exempt from regular teaching duties.";points=["General default: birds normally fly.","Specific exception: penguins normally do not fly.","University default: professors typically teach courses.","Specific exception: visiting professors may be exempt.","The reasoner should explain why the default was defeated."];trace="Evaluate general default → check for specific exception → exception takes precedence."}
 else if(/viva|exam|interview question/.test(l)){title="Viva preparation";body="Prepare concise definitions, examples, implementation details, and limitations. These questions cover the main project learning outcomes.";points=["Define knowledge graph and semantic network.","Differentiate ontology and taxonomy.","Explain is-a versus part-of.","Describe inheritance and property propagation.","Explain default and non-monotonic reasoning.","Describe RDF triples, OWL, and SPARQL.","Explain graph traversal and the inference trace.","Discuss limitations and future scope."];trace="Generated a project-focused viva checklist."}
 else if(/architecture|workflow|working of project/.test(l)){title="Project architecture";body="The system has a user interface, query interpreter, knowledge graph, inference engine, and answer explanation layer. A question is interpreted, relevant entities and edges are retrieved, rules derive additional facts, and the system returns an answer with evidence.";points=["UI: assistant, graph explorer, builder, and analytics.","Query interpreter: intent and entity matching.","Graph store: nodes, edges, properties, and metadata.","Inference engine: transitivity, inheritance, defaults, exceptions.","Answer layer: conclusion, evidence, and proof trace."];trace="User query → interpretation → graph traversal → inference → explainable answer."}
 else if(best){title=best.title;body=best.body;points=best.points||[];trace=best.trace||"Matched a curated domain knowledge entry."}
 else if(exact){title=`Knowledge about ${exact.name}`;body=exact.description;points=exact.properties;trace="Matched an entity in the editable graph."}
 else {title="I couldn't find a reliable answer in this knowledge pack";body="This assistant uses a broad curated offline knowledge pack plus your editable graph. It does not invent facts when a question is outside its coverage. Try rephrasing with a key term such as ontology, inheritance, RDF, OWL, SPARQL, Neo4j, default reasoning, graph traversal, or ask about a concept in the Knowledge Library.";points=["Try: Explain ontology vs taxonomy.","Try: How does is-a inheritance work?","Try: What is non-monotonic reasoning?","Try: How do RDF and SPARQL work together?","Try: Explain the project architecture."];trace="No sufficiently relevant knowledge entry or graph entity was matched."}
 return {title,body,points,trace}}
function appendMessage(q,ans){let host=$("#chatMessages");let u=document.createElement("div");u.className="message user";u.innerHTML=`<div class="bubble"><p>${esc(q)}</p></div>`;host.append(u);let b=document.createElement("div");b.className="message bot";b.innerHTML=`<div class="bot-icon">G✳</div><div class="bubble"><b>${esc(ans.title)}</b><p>${esc(ans.body)}</p>${ans.points.length?`<ul>${ans.points.map(p=>`<li>${esc(p)}</li>`).join("")}</ul>`:""}<p><b>Reasoning / evidence trace</b><br>${esc(ans.trace)}</p><small>LOCAL KNOWLEDGE PACK · EXPLAINABLE RESPONSE</small></div>`;host.append(b);host.scrollTop=host.scrollHeight}
function ask(q){if(!q.trim())return;let ans=answer(q);appendMessage(q,ans);$("#chatInput").value=""}
$("#sendBtn").addEventListener("click",()=>ask($("#chatInput").value));$("#chatInput").addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();ask(e.target.value)}});$("#clearChat").addEventListener("click",()=>{$("#chatMessages").innerHTML="";toast("Conversation cleared.")});
$("#entityForm").addEventListener("submit",e=>{e.preventDefault();let name=$("#newName").value.trim(),id=name.toLowerCase().replace(/[^a-z0-9]+/g,"-");if(db.entities.some(x=>x.name.toLowerCase()===name.toLowerCase()))return toast("Entity already exists.");db.entities.push({id,name,category:$("#newType").value,description:$("#newDesc").value||"User-created concept.",properties:$("#newProps").value.split(",").map(x=>x.trim()).filter(Boolean)});save();e.target.reset();toast("Entity created and saved.")});
$("#edgeForm").addEventListener("submit",e=>{e.preventDefault();let s=$("#source").value,r=$("#predicate").value,t=$("#target").value;if(!s||!t||s===t)return toast("Choose two different entities.");if(db.relations.some(x=>x[0]===s&&x[1]===r&&x[2]===t))return toast("Relationship already exists.");db.relations.push([s,r,t]);save();toast("Semantic relation added.")});
["source","target","predicate"].forEach(id=>$("#"+id).addEventListener("change",preview));$("#entitySearch").addEventListener("input",e=>renderEntities(e.target.value));$("#librarySearch").addEventListener("input",e=>renderLibrary(e.target.value));
$("#entityRows").addEventListener("click",e=>{let b=e.target.closest("[data-delete]");if(!b)return;let id=b.dataset.delete;db.entities=db.entities.filter(x=>x.id!==id);db.relations=db.relations.filter(x=>x[0]!==id&&x[2]!==id);save();toast("Entity and its connected edges removed.")});
$("#libraryGrid").addEventListener("click",e=>{let c=e.target.closest("[data-open]");if(c){let en=E(c.dataset.open);nav("assistant");ask("Explain "+en.name)}});
$("#runReason").addEventListener("click",()=>{renderDerived();toast("Inference completed: "+derive().length+" conclusions.")});$("#zoomIn").addEventListener("click",()=>{zoom=Math.min(1.3,zoom+.1);drawGraph()});$("#zoomOut").addEventListener("click",()=>{zoom=Math.max(.7,zoom-.1);drawGraph()});$("#fitGraph").addEventListener("click",()=>{zoom=1;drawGraph()});
function exportData(){let blob=new Blob([JSON.stringify({entities:db.entities,relations:db.relations,derivedFacts:derive()},null,2)],{type:"application/json"});let u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="graphmind-knowledge-graph.json";a.click();URL.revokeObjectURL(u);toast("Knowledge graph JSON exported.")}$("#exportBtn").addEventListener("click",exportData);
function showQuiz(){let q=quiz[qi];$("#quizProgress").textContent=`QUESTION ${qi+1} / ${quiz.length}`;$("#quizQuestion").textContent=q[0];$("#quizOptions").innerHTML=q[1].map((o,i)=>`<button data-option="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join("");$("#quizFeedback").textContent="";$("#score").textContent="SCORE "+score;$("#nextQuiz").disabled=true;answered=false}
$("#quizOptions").addEventListener("click",e=>{let b=e.target.closest("[data-option]");if(!b||answered)return;answered=true;let n=Number(b.dataset.option),q=quiz[qi];$$("[data-option]").forEach((x,i)=>{if(i===q[2])x.classList.add("correct");else if(i===n)x.classList.add("wrong")});if(n===q[2]){score++;$("#quizFeedback").textContent="Correct! "+q[3]}else $("#quizFeedback").textContent="Not quite. "+q[3];$("#score").textContent="SCORE "+score;$("#nextQuiz").disabled=false});
$("#nextQuiz").addEventListener("click",()=>{if(qi<quiz.length-1){qi++;showQuiz()}else{$("#quizQuestion").textContent=`Quiz complete — you scored ${score} out of ${quiz.length}.`;$("#quizOptions").innerHTML="";$("#quizFeedback").textContent="Restart to practise again.";$("#nextQuiz").disabled=true}});
$("#restartQuiz").addEventListener("click",()=>{qi=0;score=0;showQuiz()});
function init(){refresh();fillSelects();renderEntities();renderLibrary();drawGraph();renderDerived();showQuiz();}init();